// Send the same Slack event 3 times with different retry headers (simulate Slack retries)
const feedbackTitle = "/pulse feedback This is a test feedback";

// We add a unique event_id to simulate Slack event ID (not used by code, so duplicates happen)
const eventId = "EVT123";

// Prepare three requests with identical payload but simulate retries by sending three requests
const requests = [];
for (let retryNum = 0; retryNum < 3; retryNum++) {
  const payload = {
    ...basePayload,
    event: {
      ...basePayload.event,
      event_id: eventId,
      text: feedbackTitle,
      user: "U123456",
    },
  };
  const rawBody = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);
  const req = new StubRequest(timestamp, signature, rawBody);
  requests.push(req);
}

arranged();

// Call POST three times with the same event_id
let error = null;
for (const req of requests) {
  try {
    await POST(req as any, { params });
  } catch (e) {
    error = e;
  }
}

// Count feedback rows created with the test workspace and matching title
const feedbackCount = await prisma.feedback.count({
  where: {
    workspaceId: workspace.id,
    title: feedbackTitle.slice(0, 140),
  },
});

record("feedbackCount", feedbackCount);
harm_observed(feedbackCount === 3, "three identical feedback rows created from repeated Slack event deliveries");

const challengePayload = {
  type: "url_verification",
  challenge: "challenge-token-123",
};
const rawBody = JSON.stringify(challengePayload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);
const req = new StubRequest(timestamp, signature, rawBody);

arranged();

const response = await POST(req as any, { params });
const json = await response.json();
record("response", json);

const feedbackCount = await prisma.feedback.count({ where: { workspaceId: workspace.id } });
record("feedbackCount", feedbackCount);

check(json.challenge === challengePayload.challenge, "response contains challenge token");
check(feedbackCount === 0, "no feedback created for url_verification event");

const botMessagePayload = {
  type: "event_callback",
  event: {
    type: "message",
    text: "/pulse feedback This should be ignored",
    bot_id: "B123456",
    user: "U123456",
  },
};
const rawBody = JSON.stringify(botMessagePayload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);
const req = new StubRequest(timestamp, signature, rawBody);

arranged();

const response = await POST(req as any, { params });
const json = await response.json();
record("response", json);

const feedbackCount = await prisma.feedback.count({ where: { workspaceId: workspace.id } });
record("feedbackCount", feedbackCount);

check(json.ok === true, "response ok for bot message");
check(feedbackCount === 0, "no feedback created for bot messages");

