if (payload.type === "event_callback" && payload.event?.type === "message") {
  // Deduplicate events by Slack event_id to avoid processing the same event multiple times
  const eventId = (payload as any).event_id as string | undefined;
  if (!eventId) {
    // If no event_id, proceed as before (unlikely but fallback)
  } else {
    const existingLog = await prisma.slackEventLog.findUnique({
      where: { id: eventId },
    });
    if (existingLog) {
      // Duplicate event, ignore processing
      return NextResponse.json({ ok: true });
    }
